import type {
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error, parseReservationCommand, reservationResponse } from "./reservation";
import { isId, isQuantity, isRecord, isRevision, isUnits } from "./validation";

type ReadResult =
  | { kind: "found"; value: unknown }
  | { kind: "missing" }
  | { kind: "unavailable" };

const decimalPattern = /^(0|[1-9][0-9]*)$/;

function encodeDecimal(value: number): string {
  return String(value);
}

function decodeDecimal(value: unknown): number | undefined {
  if (typeof value !== "string" || !decimalPattern.test(value)) return undefined;
  const decoded = Number(value);
  return Number.isSafeInteger(decoded) ? decoded : undefined;
}

function decodeBoundedUnits(value: unknown): number | undefined {
  const decoded = decodeDecimal(value);
  return decoded !== undefined && isUnits(decoded) ? decoded : undefined;
}

function decodeBoundedQuantity(value: unknown): number | undefined {
  const decoded = decodeDecimal(value);
  return decoded !== undefined && isQuantity(decoded) ? decoded : undefined;
}

function decodeStockRow(value: unknown): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey)) return undefined;
  const totalUnits = decodeBoundedUnits(value.onHandText);
  const reservedUnits = decodeBoundedUnits(value.heldText);
  const revision = decodeDecimal(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined ||
      reservedUnits > totalUnits || revision === undefined || !isRevision(revision)) {
    return undefined;
  }
  return {
    sku: value.itemKey,
    totalUnits,
    reservedUnits,
    revision,
  };
}

function decodeReservationRow(value: unknown): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || !isId(value.itemKey)) return undefined;
  const quantity = decodeBoundedQuantity(value.unitsText);
  return quantity === undefined
    ? undefined
    : { reservationId: value.bookingKey, sku: value.itemKey, quantity };
}

async function readProviderB(
  storage: ProviderBStorage,
  collection: "inventory" | "reservations",
  key: string,
): Promise<ReadResult> {
  try {
    const envelope = await storage.read({ collection, key });
    if (!isRecord(envelope)) return { kind: "unavailable" };
    if (envelope.ok === true) return { kind: "found", value: envelope.value };
    if (envelope.ok !== false || !isRecord(envelope.error)) return { kind: "unavailable" };
    if (envelope.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
    return { kind: "unavailable" };
  } catch {
    return { kind: "unavailable" };
  }
}

function toStockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: encodeDecimal(stock.totalUnits),
    heldText: encodeDecimal(stock.reservedUnits),
    revisionText: encodeDecimal(stock.revision),
  };
}

function toReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: encodeDecimal(reservation.quantity),
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      if (command.op === "getAvailability") {
        const read = await readProviderB(storage, "inventory", command.sku);
        if (read.kind === "missing") return error(404, "stock_not_found");
        if (read.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = decodeStockRow(read.value);
        if (stock === undefined || stock.sku !== command.sku) return error(500, "storage_unavailable");
        return {
          status: 200,
          body: {
            sku: stock.sku,
            totalUnits: stock.totalUnits,
            reservedUnits: stock.reservedUnits,
            availableUnits: stock.totalUnits - stock.reservedUnits,
          },
        };
      }

      const reservationRead = await readProviderB(storage, "reservations", command.reservationId);
      if (reservationRead.kind === "unavailable") return error(500, "storage_unavailable");
      const existing = reservationRead.kind === "found"
        ? decodeReservationRow(reservationRead.value)
        : undefined;
      if (reservationRead.kind === "found" &&
          (existing === undefined || existing.reservationId !== command.reservationId)) {
        return error(500, "storage_unavailable");
      }
      if (command.op === "getReservation") {
        return existing === undefined ? error(404, "reservation_not_found") : reservationResponse(200, existing);
      }
      if (existing !== undefined) {
        return existing.sku === command.sku && existing.quantity === command.quantity
          ? reservationResponse(200, existing)
          : error(409, "reservation_conflict");
      }

      const stockRead = await readProviderB(storage, "inventory", command.sku);
      if (stockRead.kind === "missing") return error(404, "stock_not_found");
      if (stockRead.kind === "unavailable") return error(500, "storage_unavailable");
      const stock = decodeStockRow(stockRead.value);
      if (stock === undefined || stock.sku !== command.sku) return error(500, "storage_unavailable");
      if (stock.totalUnits - stock.reservedUnits < command.quantity) {
        return error(409, "insufficient_stock");
      }
      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

      const reservation: Reservation = {
        reservationId: command.reservationId,
        sku: command.sku,
        quantity: command.quantity,
      };
      const nextStock = {
        ...stock,
        reservedUnits: stock.reservedUnits + reservation.quantity,
        revision: nextRevision,
      };
      const reservationRow = toReservationRow(reservation);
      try {
        const outcome = await storage.commitBatch({
          expectedRevisionText: encodeDecimal(stock.revision),
          stockRow: toStockRow(nextStock),
          reservationRow,
          outboxRows: [{
            key: "reservation.created:" + reservation.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: reservationRow.bookingKey,
              itemKey: reservationRow.itemKey,
              unitsText: reservationRow.unitsText,
            },
          }],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

