import type { Service, ServiceResponse, SnapshotStock, StockReportSource } from "./types";
import { error } from "./reservation";
import { decodeSnapshotStock, isRecord, isUnits } from "./validation";

type LowStockCommand = {
  op: "lowStock";
  belowUnits: number;
};

function parseCommand(raw: unknown): LowStockCommand | undefined {
  if (!isRecord(raw)) return undefined;
  return raw.op === "lowStock" && isUnits(raw.belowUnits)
    ? { op: raw.op, belowUnits: raw.belowUnits }
    : undefined;
}

function decodeSnapshot(value: unknown): SnapshotStock[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const seenSkus = new Set<string>();
  const stocks: SnapshotStock[] = [];
  for (const row of value) {
    const stock = decodeSnapshotStock(row);
    if (stock === undefined || seenSkus.has(stock.sku)) return undefined;
    seenSkus.add(stock.sku);
    stocks.push(stock);
  }
  return stocks;
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        const snapshot = decodeSnapshot(await source.readSnapshot());
        if (snapshot === undefined) return error(500, "storage_unavailable");
        const items = snapshot
          .filter((stock) => stock.totalUnits - stock.reservedUnits < command.belowUnits)
          .map((stock) => ({
            sku: stock.sku,
            availableUnits: stock.totalUnits - stock.reservedUnits,
          }))
          .sort((left, right) => left.sku < right.sku ? -1 : left.sku > right.sku ? 1 : 0);
        return { status: 200, body: { items } };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

